// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }
    function testFuzz_property(address caller, address fuzzOwner) public {
        vm.assume(fuzzOwner != address(0));
        vm.assume(fuzzOwner != caller);
        vm.prank(c.owner());
        c.transferOwnership(fuzzOwner);
        bool isOwner = (caller == c.owner());
        vm.prank(caller);
        bool ok;
        try c.owned() { ok = true; } catch { ok = false; }
        assertTrue(ok == isOwner);
    }
}
